@import "tailwindcss";

@theme {
  --font-sans: 'Plus Jakarta Sans', sans-serif;
  --font-mono: 'JetBrains Mono', monospace;

  --color-primary: #00e599; /* Electric Green */
  --color-primary-hover: #00ffaa;

  --color-bg-base: #0d1117;
  --color-bg-surface: #161b22;
  --color-bg-surface-hover: #21262d;

  --color-text-base: #e6edf3;
  --color-text-muted: #848d97;
  --color-border-subtle: #30363d;
}

@layer base {
  :root {
    --background: #0d1117;
    --foreground: #e6edf3;

    --card: #161b22;
    --card-foreground: #e6edf3;

    --popover: #161b22;
    --popover-foreground: #e6edf3;

    --primary: #00e599;
    --primary-foreground: #000000;

    --secondary: #21262d;
    --secondary-foreground: #e6edf3;

    --muted: #21262d;
    --muted-foreground: #848d97;

    --accent: #21262d;
    --accent-foreground: #e6edf3;

    --destructive: #ff7b72;
    --destructive-foreground: #000000;

    --border: #30363d;
    --input: #30363d;
    --ring: #00e599;

    --radius: 0.5rem;
  }
}

@layer base {
  * {
    @apply border-border;
  }
  body {
    @apply bg-background text-foreground font-sans antialiased;
  }
}

/* Custom scrollbar */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}
::-webkit-scrollbar-track {
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background: var(--border);
  border-radius: 4px;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--muted-foreground);
}

/* Glass effect */
.glass {
  background: rgba(22, 27, 34, 0.7);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid var(--border);
}

/* Code block styles */
pre {
  background-color: #0d1117;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1rem;
  overflow-x: auto;
}
code {
  font-family: var(--font-mono);
  font-size: 0.875rem;
}
EOF

