import { build } from 'vite';
import react from '@vitejs/plugin-react';
import tailwindcss from '@tailwindcss/vite';
import { viteSingleFile } from 'vite-plugin-singlefile';
import { resolve } from 'path';

const pages = [
  { name: 'index', file: 'index.html' },
  { name: 'apps-build', file: 'apps-build.html' },
  { name: 'storefronts', file: 'storefronts.html' },
  { name: 'agents', file: 'agents.html' },
  { name: 'support', file: 'support.html' }
];

async function run() {
  for (const page of pages) {
    console.log(`Building ${page.name}...`);
    await build({
      configFile: false,
      plugins: [react(), tailwindcss(), viteSingleFile()],
      base: './',
      resolve: {
        alias: {
          '@': resolve(process.cwd(), './src')
        }
      },
      build: {
        emptyOutDir: false,
        outDir: 'dist',
        rollupOptions: {
          input: resolve(process.cwd(), page.file)
        }
      }
    });
  }
}

run();
EOF
